practice.starterCode:
CREATE TABLE perf15_orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, amount INTEGER NOT NULL);
WITH RECURSIVE seq(value) AS (SELECT 1 UNION ALL SELECT value + 1 FROM seq WHERE value < 200) INSERT INTO perf15_orders SELECT value, printf('Customer%03d', value % 20), value FROM seq;
CREATE INDEX idx_perf15_customer ON perf15_orders(customer);
EXPLAIN QUERY PLAN SELECT order_id, amount FROM perf15_orders WHERE customer = 'Customer007';

